#!/usr/bin/env bash
# Build a static Qt6 (qtbase only: Core/Gui/Widgets/Network/Concurrent) from
# source for single-binary FLAC-Chop Windows builds. Produces $PREFIX with a
# ready-to-use static Qt install findable via CMAKE_PREFIX_PATH.
#
# Usage: deps/build-qt6-static.sh <prefix>
# Env:   CC, CXX, CFLAGS, CXXFLAGS, LDFLAGS (honored)
#        QT6_SRC_TAG  — git tag to build (default: v6.8.3)
#
# Cacheable: re-runs are a no-op once $PREFIX/lib/cmake/Qt6/Qt6Config.cmake
# exists.
#
# Designed for MSYS2 MINGW64 (gcc) and CLANGARM64 (clang). Only qtbase is
# built — FLAC-Chop needs Widgets/Concurrent/Network, all in qtbase.
set -euo pipefail

PREFIX="${1:?usage: build-qt6-static.sh <prefix>}"
mkdir -p "$PREFIX"
PREFIX="$(cd "$PREFIX" && pwd)"

# Qt's configure forwards -prefix verbatim to native cmake's
# CMAKE_INSTALL_PREFIX. Under MSYS2, native cmake.exe does NOT understand
# MSYS paths (/d/a/...) — it installs to a mangled D:\d\a\... location, so
# the install tree never lands under $PREFIX and the published tarball ends
# up containing only the source/build tree (no lib/cmake/Qt6Widgets). Pass
# a Windows mixed path to -prefix; keep $PREFIX as the MSYS path for shell
# ops and the fast-path check below.
if command -v cygpath >/dev/null 2>&1; then
  PREFIX_ARG="$(cygpath -m "$PREFIX")"
else
  PREFIX_ARG="$PREFIX"
fi

# Fast path: already built. Check for Qt6CoreConfig.cmake (a qtbase-only build
# does NOT produce the meta Qt6Config.cmake — that's generated by the full
# Qt6 superbuild, not by qtbase alone).
if [ -f "$PREFIX/lib/cmake/Qt6Core/Qt6CoreConfig.cmake" ]; then
  echo "static Qt6 already present at $PREFIX — skipping"
  exit 0
fi

QT_TAG="${QT6_SRC_TAG:-v6.8.3}"
WORKDIR="${QT6_BUILD_WORKDIR:-$PREFIX/src}"
mkdir -p "$WORKDIR"

NJOBS="${QT6_BUILD_JOBS:-$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 2)}"

# Clone qtbase at the pinned tag (shallow).
SRC="$WORKDIR/qtbase"
if [ ! -d "$SRC/.git" ]; then
  rm -rf "$SRC"
  git clone --depth 1 --branch "$QT_TAG" https://code.qt.io/qt/qtbase.git "$SRC"
fi

BUILD="$WORKDIR/qtbase-build"
rm -rf "$BUILD"
mkdir -p "$BUILD"

cd "$BUILD"

# Qt6's configure is a cmake wrapper. -static -release gives a release static
# build. -nomake examples/tests skips the slow example/test builds. Only
# qtbase is cloned, so no other Qt modules are built.
#
# Force Qt's BUNDLED static third-party copies and disable optional features
# that would otherwise auto-detect MSYS2's SHARED system libs (zlib, pcre2,
# libb2) — a static-Qt single-exe must not import zlib1.dll/libpcre2-16-0.dll/
# libb2-1.dll. libb2 has a bundled fallback (qtbase/src/3rdparty/blake2);
# zstd/brotli are optional features FLAC-Chop doesn't need, so disable them to
# drop libzstd.dll/libbrotlidec.dll imports. Feature var names match vcpkg's
# qtbase port and Gentoo's dev-qt/qtbase ebuild (QT_FEATURE_*).
"$SRC/configure" \
  -static \
  -release \
  -prefix "$PREFIX_ARG" \
  -nomake examples \
  -nomake tests \
  -no-dbus \
  -- \
  -DQT_FEATURE_system_zlib=OFF \
  -DQT_FEATURE_system_pcre2=OFF \
  -DQT_FEATURE_system_libb2=OFF \
  -DQT_FEATURE_zstd=OFF \
  -DQT_FEATURE_brotli=OFF

cmake --build . --parallel "$NJOBS"
# cmake --install may return non-zero due to non-fatal post-install steps like
# SBOM generation. Tolerate that — but require the install tree to actually
# exist under $PREFIX. A wrong CMAKE_INSTALL_PREFIX (e.g. an MSYS /d/... path
# fed to native cmake) silently installs elsewhere and ships a useless tarball,
# so fail loudly here instead of letting the downstream find_package fail.
cmake --install . || true
test -f "$PREFIX/lib/cmake/Qt6Core/Qt6CoreConfig.cmake" || {
  echo "::error: Qt6 install tree missing lib/cmake/Qt6Core/Qt6CoreConfig.cmake under $PREFIX" >&2
  echo ":: (CMAKE_INSTALL_PREFIX was $PREFIX_ARG)" >&2
  exit 1
}

# The source + build tree under $PREFIX/src is not needed by consumers —
# CMAKE_PREFIX_PATH only uses the install tree (lib/, lib/cmake/, mkspecs/,
# plugins/). Remove it so the published tarball is install-only instead of
# ~700 MB, and to sidestep the MSYS2 tar --exclude bug that previously
# produced an empty archive.
rm -rf "$PREFIX/src"

echo ":: static Qt6 build complete at $PREFIX"
echo ":: set CMAKE_PREFIX_PATH=$PREFIX"
